INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_ARETHUSA_OVIDM','ENT_ARETHUSA','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses','Metamorphoses 5.572-641','"There is a stream in the middle, between Cyane and the Pisaean Arethusa, which is confined within itself, being enclosed by mountain ridges at a short distance {from each other}.','Henry T. Riley',1851,'https://www.gutenberg.org/ebooks/21765','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0029','primary-verbatim',NULL,true,'English translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_DAEDALUS_OVIDM','ENT_DAEDALUS','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses','Metamorphoses 8.183ff','The lot falls on Theseus, who, by the assistance of Ariadne, kills the monster, escapes from the labyrinth, which Daedalus made, and carries Ariadne to the island of Naxos, where he abandons her. Bacchus wooes her, and, to immortalize her name, he transforms the crown which he has given her into a Constellation.','Henry T. Riley',1851,'https://www.gutenberg.org/ebooks/21765','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0029','primary-verbatim',NULL,true,'English translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_DAPHNE_OVIDM','ENT_DAPHNE','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses','Metamorphoses 1.452-567','[I.452-567] Apollo, falling in love with Daphne, the daughter of the river Peneus, she flies from him. He pursues her; on which, the Nymph, imploring the aid of her father, is changed into a laurel. Daphne, the daughter of Peneus, was the first love of Phœbus; whom, not blind chance, but the vengeful anger of Cupid assigned to him.','Henry T. Riley',1851,'https://www.gutenberg.org/ebooks/21765','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0029','primary-verbatim',NULL,true,'English translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_ECHO_OVIDM','ENT_ECHO','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses','Metamorphoses 3.339-401','[III.339-401] Echo, having often amused Juno with her stories, to give time to Jupiter''s mistresses to make their escape, the Goddess, at last, punishes her for the deception. She is slighted and despised by Narcissus, with whom she falls in love. He, much celebrated by fame throughout the cities of Aonia, gave unerring answers to the people consulting him.','Henry T. Riley',1851,'https://www.gutenberg.org/ebooks/21765','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0029','primary-verbatim',NULL,true,'English translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_GLAUCUS_OVIDM','ENT_GLAUCUS','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses','Metamorphoses 13.898ff','[XIII.898-968] Glaucus having observed some fishes which he has laid upon the grass revive and leap again into the water, is desirous to try the influence of the grass on himself. Putting some of it into his mouth, he immediately becomes mad, and leaping into the sea, is transformed into a sea God. Galatea ceases speaking, and the company breaking up, they depart; and the Nereids swim in the becalmed waves.','Henry T. Riley',1851,'https://www.gutenberg.org/ebooks/21765','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0029','primary-verbatim',NULL,true,'English translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_HERMAPHRODITUS_OVIDM','ENT_HERMAPHRODITUS','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses','Metamorphoses 4.285-388','[IV.285-388] The Naiad Salmacis falls in love with the youth Hermaphroditus, who rejects her advances. While he is bathing, she leaps into the water, and seizing the youth in her arms, they become one body, retaining their different sexes. Learn how Salmacis became infamous, {and} why it enervates, with its enfeebling waters, and softens the limbs bathed {in it}.','Henry T. Riley',1851,'https://www.gutenberg.org/ebooks/21765','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0029','primary-verbatim',NULL,true,'English translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_MELICERTES_PALAEMON_OVIDM','ENT_MELICERTES_PALAEMON','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses','Metamorphoses 4.519-542','I have {surely} some interest with the sea, if, indeed, I once was foam formed in the hollowed deep, and my Grecian name is derived from that." Neptune yields to her request; and takes away from them {all} that is mortal, and gives them a venerable majesty; and alters both their name and their shape, and calls Palaemon a Divinity, together with his mother Leucothoë.','Henry T. Riley',1851,'https://www.gutenberg.org/ebooks/21765','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0029','primary-verbatim',NULL,true,'English translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_MORPHEUS_OVIDM','ENT_MORPHEUS','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses','Metamorphoses 11.635','Juno sends Iris to the God of Sleep, who, at her request, dispatches Morpheus to Halcyone, in a dream, to inform her of the death of her husband. She awakes in the morning, full of solicitude, and goes to the shore where she finds the body of Ceyx thrown up by the waves. She is about to cast herself into the sea in despair, when the Gods transform them both into king-fishers.','Henry T. Riley',1851,'https://www.gutenberg.org/ebooks/21765','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0029','primary-verbatim',NULL,true,'English translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_ORPHNE_OVIDM','ENT_ORPHNE','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses','Metamorphoses 5.539-541','Ascalaphus alone, of all persons, had seen this, whom Orphne, by no means the most obscure among the Nymphs of Avernus, is said once to have borne to her own Acheron within {his} dusky caves. He beheld {this}, and cruelly prevented her return by his discovery.','Henry T. Riley',1851,'https://www.gutenberg.org/ebooks/21765','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0029','primary-verbatim',NULL,true,'English translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_PHANTASOS_OVIDM','ENT_PHANTASOS','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses','Metamorphoses 11.642','There is likewise a third, {master} of a different art, {called} Phantasos: he cleverly changes {himself} into earth, and stone, and water, and a tree, and all those things which are destitute of life. These are wont, by night, to show their features to kings and to generals, {while} others wander amid the people and the commonalty.','Henry T. Riley',1851,'https://www.gutenberg.org/ebooks/21765','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0029','primary-verbatim',NULL,true,'English translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_PHOBETOR_OVIDM','ENT_PHOBETOR','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses','Metamorphoses 11.640','But he imitates men only; for another one becomes a wild beast, becomes a bird, {or} becomes a serpent, with its lengthened body: this one, the Gods above call Icelos; the tribe of mortals, Phobetor. There is likewise a third, {master} of a different art, {called} Phantasos: he cleverly changes {himself} into earth, and stone, and water, and a tree, and all those things which are destitute of life.','Henry T. Riley',1851,'https://www.gutenberg.org/ebooks/21765','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0029','primary-verbatim',NULL,true,'English translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_ROM_DIVUS_JULIUS_OVIDM','ENT_ROM_DIVUS_JULIUS','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses','Metamorphoses 15.745-870','This was Octavius, the adopted son of Julius Caesar. According to Suetonius, he traced his descent, through his mother, from Ascanius or Iülus.] [Footnote 51: _Ought not to fill._--Ver. 462. Clarke''s quaint translation is, ''And let us not cram our g--ts with Thyestian victuals.''] [Footnote 52: _Feather foils._--Ver. 475.','Henry T. Riley',1851,'https://www.gutenberg.org/ebooks/21765','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0029','primary-verbatim',NULL,true,'English translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_ROM_POMONA_OVIDM','ENT_ROM_POMONA','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses','Metamorphoses 14.623-771','[XIV.609-697] Vertumnus, enamoured of Pomona, assumes several shapes for the purpose of gaining her favour; and having transformed himself into an old woman, succeeds in effecting his object. From that time Alba and the Latin state were under the sway of Ascanius with the two names; Sylvius succeeded him; sprung of whom, Latinus had a renewed name, together with the ancient sceptre.','Henry T. Riley',1851,'https://www.gutenberg.org/ebooks/21765','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0029','primary-verbatim',NULL,true,'English translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_ROM_VERTUMNUS_OVIDM','ENT_ROM_VERTUMNUS','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses','Metamorphoses 14.623-771','[XIV.609-697] Vertumnus, enamoured of Pomona, assumes several shapes for the purpose of gaining her favour; and having transformed himself into an old woman, succeeds in effecting his object. From that time Alba and the Latin state were under the sway of Ascanius with the two names; Sylvius succeeded him; sprung of whom, Latinus had a renewed name, together with the ancient sceptre.','Henry T. Riley',1851,'https://www.gutenberg.org/ebooks/21765','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0029','primary-verbatim',NULL,true,'English translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_SALMACIS_OVIDM','ENT_SALMACIS','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses','Metamorphoses 4.285-388','[IV.285-388] The Naiad Salmacis falls in love with the youth Hermaphroditus, who rejects her advances. While he is bathing, she leaps into the water, and seizing the youth in her arms, they become one body, retaining their different sexes. Learn how Salmacis became infamous, {and} why it enervates, with its enfeebling waters, and softens the limbs bathed {in it}.','Henry T. Riley',1851,'https://www.gutenberg.org/ebooks/21765','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0029','primary-verbatim',NULL,true,'English translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_SYRINX_OVIDM','ENT_SYRINX','SRC_OVID_METAMORPHOSES','Ovid, Metamorphoses','Metamorphoses 1.689-712','[I.689-712] Pan, falling in love with the Nymph Syrinx, she flies from him; on which he pursues her. Syrinx, arrested in her flight by the waves of the river Ladon, invokes the aid of her sisters, the Naiads, who change her into reeds. Pan unites them into an instrument with seven pipes, which bears the name of the Nymph.','Henry T. Riley',1851,'https://www.gutenberg.org/ebooks/21765','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0029','primary-verbatim',NULL,true,'English translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1)
